<template>
  <section class="login-page">
    <div class="login-art"><div class="brand light-brand"><span class="brand-mark">鲜</span><span><b>鲜选</b><small>FRESH SELECT</small></span></div><div class="login-hero"><span class="eyebrow">WELCOME TO FRESH SELECT</span><h1>新鲜，<br/><i>即刻到家。</i></h1><p>每天为你精选新鲜好物，<br/>让好生活从一餐开始。</p><div class="login-fruits">🍎　🥬　🍊</div></div></div>
    <div class="login-panel"><div class="login-card"><span class="eyebrow">MEMBER LOGIN</span><h2>欢迎回来</h2><p>登录后享受会员专属权益</p><label>账号 / 手机号</label><input v-model.trim="account" placeholder="请输入账号或手机号"/><label>密码</label><input v-model="password" type="password" placeholder="请输入密码" @keyup.enter="login"/><div class="login-options"><label><input type="checkbox" checked/> 记住我</label><a>忘记密码？</a></div><button class="primary full" @click="login">登录鲜选</button><div class="divider"></div><p class="register">还没有账号？ <b @click="openRegister">立即注册</b></p><p v-if="error" class="login-error">{{ error }}</p></div></div>
    <div v-if="showRegister" class="register-overlay" @click.self="showRegister = false"><form class="register-modal" @submit.prevent="submitRegister"><button type="button" class="register-close" @click="showRegister = false">×</button><span class="eyebrow">JOIN FRESH SELECT</span><h2>立即注册</h2><p>注册鲜选账号，开启新鲜生活</p><label>用户名</label><input v-model.trim="registerForm.username" required minlength="2" maxlength="20" placeholder="请输入用户名"/><label>手机号</label><input v-model.trim="registerForm.phone" required pattern="1[3-9]\d{9}" placeholder="请输入手机号"/><label>设置密码</label><input v-model="registerForm.password" required minlength="6" type="password" placeholder="至少 6 位密码"/><label>确认密码</label><input v-model="registerForm.confirmPassword" required minlength="6" type="password" placeholder="请再次输入密码"/><p v-if="registerError" class="register-error">{{ registerError }}</p><button class="primary full" type="submit">完成注册</button><p class="register-switch">已有账号？ <b @click="showRegister = false">返回登录</b></p></form></div>
  </section>
</template>
<script setup>
import { reactive, ref, inject } from 'vue'
import { useRouter, useRoute } from 'vue-router'
const account = ref(''), password = ref(''), error = ref(''), showRegister = ref(false), registerError = ref(''), router = useRouter(), route = useRoute(), notify = inject('notify')
const registerForm = reactive({ username: '', phone: '', password: '', confirmPassword: '' })
const createToken = role => { const payload = { sub: account.value || 'demo', role, exp: Date.now() + 30 * 60 * 1000 }; return btoa(JSON.stringify(payload)).replaceAll('+', '-').replaceAll('/', '_').replaceAll('=', '') }
const login = () => { error.value = ''; if (!account.value || !password.value) { error.value = '请输入账号和密码'; return }; const role = account.value.toLowerCase() === 'admin2026' ? 'admin' : 'user'; const expectedPassword = role === 'admin' ? '123456' : (localStorage.getItem('fresh_demo_password') || '123456'); if (password.value !== expectedPassword) { error.value = role === 'admin' ? '管理员演示密码为 123456' : '账号或密码不正确'; return }; const token = createToken(role); sessionStorage.setItem('fresh_token', token); sessionStorage.setItem('fresh_role', role); if (role === 'admin') window.location.href = `${window.location.origin}/admin.html?token=${encodeURIComponent(token)}&role=admin`; else { notify('登录成功'); router.push(route.query.redirect || '/home') } }
const openRegister = () => { registerError.value = ''; showRegister.value = true }
const submitRegister = () => { registerError.value = ''; if (registerForm.password !== registerForm.confirmPassword) { registerError.value = '两次输入的密码不一致'; return }; localStorage.setItem('fresh_demo_password', registerForm.password); account.value = registerForm.phone; password.value = registerForm.password; showRegister.value = false; notify('注册成功，请登录') }
</script>
